entries[206466] = { ["name"] = "Essenz der Nacht", ["text"] = "Sofort\nWenn trügerische Blutzähne sterben, wird eine 'Essenz der Nacht' erschaffen. Dieser Effekt erhöht den gesamten Schaden und die gesamte Heilung um 30%, solange sich die Spielercharaktere innerhalb des Effektbereichs von 'Illusionäre Nacht' befinden. Zusätzlich wird die Manaregeneration um 2% erhöht.\n\nDieser Effekt hält nach dem Verlassen der Illusion noch 30 Sek. lang an." }
