entries[206474] = { ["name"] = "Sucherschwarm", ["text"] = "300 Meter Reichweite\nSofort\nTichondrius entfesselt eine Welle chaotischer Magie auf alle Spielercharaktere, die von 'Aasseuche' betroffen sind. Dieser Effekt fügt allen Spielercharakteren in einer Linie zu jedem Ziel 13409 Schattenschaden zu. Zusätzlich belegt dieser Effekt alle getroffenen Spielercharaktere mit 'Aasseuche'." }
