entries[206499] = { ["name"] = "Flammen von Sargeras", ["text"] = "Unbegrenzte Reichweite\nSofort\nUmgibt ein Ziel nach 3 Sek. mit Flammen und verbrennt es 3 Sek. lang. Pro Sekunde des Brennens explodiert es und fügt Verbündeten innerhalb von 8 Metern 2134 Schaden und zusätzlich 6717 Feuerschaden zu.\n\nGetroffene Ziele hinterlassen Glutreste an ihrer Position, die wiederum explodieren, Zielen innerhalb von 5 Metern 12818 Feuerschaden zufügen und einen Bereich verwüsteten Bodens hinterlassen." }
