entries[206930] = { ["name"] = "Herzstoß", ["text"] = "1 Rune / -15 Runenmacht Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt das Ziel sowie einen weiteren Gegner in der Nähe sofort, verursacht (57.005% der Angriffskraft) körperlichen Schaden und verringert die Bewegungsgeschwindigkeit der Gegner 8 Sek. lang um 20%. [ Herzstoß : Erzeugt 5 zusätzliche Runenmacht ] [ Herzbrecher : und 2 Runenmacht pro zusätzlich getroffenem Gegner ]." }
entries[206931] = { ["name"] = "Bluttrinker", ["text"] = "1 Rune / -10 Runenmacht 30 Meter Reichweite\nKanalisiert (Wirken in 3 sek.) 30 sek. Abklingzeit\nEntzieht dem Ziel im Verlauf von 3 Sek. 9 Gesundheit. Der Euch vom Ziel zugefügte Schaden wird während der Dauer und 5 Sek. nach vollständiger Kanalisierung 15% verringert.\n\nIhr könnt Euch bewegen, parieren, ausweichen und defensive Fähigkeiten einsetzen, während Ihr diese Fähigkeit kanalisiert.\n\nErzeugt während der Dauer 20 zusätzliche Runenmacht." }
entries[206932] = { ["name"] = "Arkane Rüstung", ["text"] = "Sofort\nDiese kleinen arkanen Schrubber sind beinahe unzerstörbar und fügen Gegnern in der Nähe 12731 Arkanschaden zu, während sie fleißig ihrer Arbeit nachgehen.\nWürde jemand allerdings die Ansaugstutze eines Schrubbers verstopfen, würde dies zu katastrophalen Ergebnissen führen." }
entries[206935] = { ["name"] = "Blutige Vergeltung", ["text"] = "Sofort 1.5 min Abklingzeit\nWährend dieser Effekt aktiv ist, werden Gegner, die den Todesritter mit Nahkampffähigkeiten treffen, mit der Blutseuche infiziert. Ist der Gegner bereits infiziert, verursacht die Blutseuche ihren Schaden sofort 3-mal. 6 Aufladungen. Hält 15 Sek. lang an.\n(1s Abklingzeit)" }
entries[206936] = { ["name"] = "Eisiger Ausstoß", ["text"] = "Sofort\nErschafft eine Kugel aus Frost, die nach kurzer Zeit zerbricht, getroffenen Zielen sofort 15805 Frostschaden sowie 10 Sek. lang alle 2 Sek. 12802 Frostschaden zufügt und sie im Verlauf von 10 Sek. allmählich verlangsamt, bis sie komplett anhalten und mit 'Zertrümmern' belegt werden." }
