entries[207217] = { ["name"] = "Anhänger: Taran Zhu", ["text"] = "Sofort\nTaran Zhu ist der fähige Kämpfer und furchtlose Anführer der Shado-Pan, einem Orden, der sich dem Schutz von Pandaria vor dem Sha gewidmet hat." }
