entries[207219] = { ["name"] = "Anhänger: Der Affenkönig", ["text"] = "Sofort\nDer Affenkönig war der zuverlässige Begleiter von Shaohao, Kaiser von ganz Pandaria. Er ist gewitzt und schelmisch und weiß von ungeahnten Geheimnissen aus der Vergangenheit Pandarias." }
entries[207220] = { ["name"] = "Anhänger: Angus Eisenfaust", ["text"] = "Sofort\nAngus Eisenfaust war von jüngster Kindheit an von Kampfeswillen durchdrungen. Er liebt es, sich mit dem Gegner von Angesicht zu Angesicht wiederzufinden, und bezwingt ihn mit einer Kombination aus Kampfkunst, Grifftechniken, Ringen und gut abgepassten Schlägen und Tritten." }
entries[207221] = { ["name"] = "Schlafen" }
entries[207222] = { ["name"] = "Anhänger: Hiro", ["text"] = "Sofort\nHiro hat lange Zeit die Welt durchwandert, ziellos eine Taverne nach der anderen auf der Suche nach dem nächsten Getränk durchstreift. Lasst Euch nicht von seinem abgerissenen Äußeren verwirren. Er hat nicht nur ein Herz aus Gold, sondern wird mit jedem Getränk auch zu einem noch besseren Kämpfer." }
entries[207223] = { ["name"] = "Anhängerin: Sylara Stahlsang", ["text"] = "Sofort\nSylara Schattenherz ist eine geheimnisvolle Wanderin, die selten über ihre Vergangenheit spricht. Eins ist jedoch klar: Nichts macht sie wütender als Ungerechtigkeit. Jeder, der sich ihr in den Weg stellt, bekommt ihre Zwillingsklingen zu spüren." }
entries[207224] = { ["name"] = "Quest Credit" }
entries[207225] = { ["name"] = "Anhängerin: Aegira", ["text"] = "Sofort\nAegira ist eine Braumeisterin der Vrykul, die in der Gunst Odyns steht. Ihre Braukunst ist legendär. Nur wenige wissen, dass ihre Kampfkunst ihr in nichts nachsteht. Sie wuchs auf dem Schlachtfeld auf und ist bisher ungeschlagen." }
