entries[207228] = { ["name"] = "Nachtbrunnen verzerren", ["text"] = "500 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde verzerrt den Nachtbrunnen und fügt allen Spielercharakteren 3161 Arkanschaden zu.\n\nJeder Einsatz dieses Zaubers erhöht den Schaden weiterer Verzerrungen des Zaubernden um 20%." }
