entries[207230] = { ["name"] = "Frostsichel", ["text"] = "2 Runen 8 Meter Reichweite\nSofort\nEin weitreichender Angriff, der allen Gegnern vor Euch (40% der Angriffskraft) Frostschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nVerbraucht 'Tötungsmaschine', damit kritische Treffer 4-mal mehr als den üblichen Schaden verursachen." }
