entries[207235] = { ["name"] = "Anhänger: Celestos", ["text"] = "Sofort\nKonsul Celestos ist einer der ältesten und ehrwürdigsten Elementare des Himmelswalls.\n\nUnter Al'Akirs Herrschaft war Celestos der Hauptberater und Taktiker bei vielen Feldzügen des Windlords." }
entries[207236] = { ["name"] = "Anhänger: Nobundo", ["text"] = "Sofort\nScharfseher Nobundo ist ein ehemaliger Paladin, der als Erster seines Volkes zum Schamanen wurde und die Elemente studierte.\n\nEr ist einer der weisesten und mächtigsten Schamanen des Irdenen Rings und war ehemals dessen Anführer." }
entries[207237] = { ["name"] = "Anhänger: Rehgar Erdenwut", ["text"] = "Sofort\nRehgar Erdenwut ist ein mächtiger Elementarschamane und ein ehemaliger Gladiator, der die Kunst des Kampfes gemeistert hat.0[Quellwert] Der Irdene Ring hat nur wenige Anhänger, die über Rehgars Erfahrung und Können auf dem Schlachtfeld verfügen.", ["unresolvedValues"] = true }
entries[207238] = { ["name"] = "Anhänger: Scaldius", ["text"] = "Sofort\nBaron Scaldius war ehemals Leutnant von Ragnaros und dient nun dem Feuerlord Glimmeron mit unerschütterlicher Ergebenheit.0[Quellwert] Baron Scaldius befiehlt die Macht und den Zorn der Feuerlande, um jeden einzelnen Gegner niederzustrecken, der ihm über den Weg läuft.", ["unresolvedValues"] = true }
entries[207239] = { ["name"] = "Anhänger: Lavinius", ["text"] = "Sofort\nAls einer der großen Steinlords von Tiefenheim ist Lavinius bekanntlich praktisch unverwüstlich.0[Quellwert] Lavinius ignoriert Empfindungen der Sterblichen wie Furcht und Schmerz und erfüllt den Willen seines Meisters mit eiserner Konzentration.", ["unresolvedValues"] = true }
entries[207240] = { ["name"] = "Anhänger: Muln Erdenwut", ["text"] = "Sofort\nMuln Erdenwut ist ein ehemaliger Anführer des Irdenen Rings und gehört zu den bedeutendsten Schamanen seiner Generation.0[Quellwert] Seine beeindruckende Ausstrahlung auf dem Schlachtfeld und seine Meisterschaft des \"traditionellen\" Schamanismus machen ihn zu einem wertvollen Verbündeten.", ["unresolvedValues"] = true }
