entries[207256] = { ["name"] = "Auslöschung", ["text"] = "Sofort\nSolange 'Säule des Frosts' aktiv ist, gewähren 'Froststoß' [ Unaufhaltbarer Gletscher : 'Unaufhaltbarer Gletscher' ] und 'Heulende Böe' immer 'Tötungsmaschine' und haben eine Chance von 20%, eine Rune zu erzeugen.\n\nWährend 'Säule des Frosts' sorgt 'Runenwaffe verstärken' außerdem dafür, dass Euer nächster Einsatz von 'Auslöschen' oder 'Frostsichel' keine Runen kostet.\n(500ms Abklingzeit)" }
