entries[207311] = { ["name"] = "Reißende Schatten", ["text"] = "Ersetzt Geißelstoß\n1 Rune / -10 Runenmacht 30 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht (135.355% der Angriffskraft) Schattenschaden und lässt eine 'Schwärende Wunde' aufbrechen.\n\nKritische Treffen lassen die 'Schwärende Wunde' aufbrechen und verursachen 20% mehr Schaden." }
