entries[207319] = { ["name"] = "Leichenschild", ["text"] = "Sofort 1 min Abklingzeit\nFür die nächsten 10 Sek. werden 90% Eures gesamten erlittenen Schadens auf [ Schlickspucker : Eure Monstrosität ] [ Glyphe 'Spuk' : Euren Spuk / Euren Ghul ] übertragen.\n\nFalls [ Schlickspucker : Eure Monstrosität ] [ Glyphe 'Spuk' : Euer Spuk / Euer Ghul ] getötet wird, während dieser Effekt aktiv ist, kann Eure Kreatur 30 Sek. lang nicht erneut beschworen werden." }
entries[207320] = { ["name"] = "Folter der tausend Seelen", ["text"] = "Ca. 1 Procs pro Minute\nWenn Ihr 'Seelenspalter' einsetzt, besteht eine Chance, dass die Kriegsklingen der Aldrachi 'Folter der tausend Seelen' entfesseln. Dieser Effekt fügt allen Gegnern innerhalb von 6 Metern (94.5% der Angriffskraft) Feuerschaden zu und heilt Euch im Verlauf von 10 Sek. um 20% Eurer Gesundheit." }
