entries[207355] = { ["name"] = "Panikinstinkt", ["text"] = "Rang 1/ 1 Artefakt Boni\n100 Meter ReichweiteBenötigt Sharas'dal, Szepter der Gezeiten\nErhöht Eure gesamte hervorgerufene Heilung um 25%, während [ Heldentum : 'Heldentum' / 'Kampfrausch'] aktiv ist." }
