entries[207358] = { ["name"] = "Gezeitenbecken", ["text"] = "Rang 1/ 1 Artefakt Boni\n100 Meter ReichweiteBenötigt Sharas'dal, Szepter der Gezeiten\n'Springflut' hat eine Chance, ein Totem der Gezeiten an der Position des Ziels zu beschwören. Das Totem der Gezeiten heilt Verbündete in der Nähe im Verlauf von 6 Sek. um (7 * (6.25% der Zaubermacht)) Gesundheit.\n(Procchance: 20%)" }
