entries[207399] = { ["name"] = "Totem des Schutzes der Ahnen", ["text"] = "2.2% von Grundmana 40 Meter Reichweite\nSofort 5 min Abklingzeit\nBeschwört für 30 Sek. ein Totem am Zielort. Alle Verbündeten innerhalb von [ Totemische Konzentration : 23 / 20] Metern um das Totem erhalten um 10% erhöhte Gesundheit. Wenn ein Verbündeter stirbt, wird das Totem aufgezehrt und gestattet ihm die Reinkarnation mit 20% Gesundheit und Mana.\n\nKann keinen Verbündeten reinkarnieren, der an massivem Schaden gestorben ist." }
